// Generates the library's built-in `DevicePresets` catalog from the JSON device
// specs in `device_specs/` (copied from flutter_device_preview, where they are
// the source of truth for the Flutter package's `DevicePresets`).
//
// One `device_specs/<id>.json` in, one `DevicePreset` property out: the screen
// size, pixel ratio, safe areas, frame artwork (screen outline and body), the
// status bar and gesture pill artwork (`systemUi`) and the keyboard heights.
// The generated file lands in the build directory and is wired into
// `commonMain` by `build.gradle.kts`, so the specs stay the only thing to edit.
//
// The specs also describe fold display features, which this library does not
// simulate (yet), and `systemUi.platform`: both are accepted and ignored.

import groovy.json.JsonSlurper

abstract class GenerateDevicePresetsTask : DefaultTask() {

    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val specFiles: ConfigurableFileCollection

    @get:OutputDirectory
    abstract val outputDirectory: DirectoryProperty

    @TaskAction
    fun generate() {
        // Sorted by id so `fold-8` precedes `fold-8-ultra`, as in Flutter.
        val files = specFiles.files.sortedBy { it.nameWithoutExtension }
        if (files.isEmpty()) throw GradleException("No device specs found")

        val ids = mutableSetOf<String>()
        val names = mutableMapOf<String, String>()
        val presets = files.map { file ->
            @Suppress("UNCHECKED_CAST")
            val spec = try {
                JsonSlurper().parse(file) as? Map<String, Any?>
            } catch (error: Exception) {
                throw GradleException("${file.name} is not valid JSON: ${error.message}", error)
            } ?: throw GradleException("${file.name} must contain a JSON object")
            val id = string(spec, "id", file.name)
            if ("$id.json" != file.name) {
                throw GradleException("${file.name} declares id \"$id\"; the file must be named \"$id.json\"")
            }
            if (!ids.add(id)) throw GradleException("Duplicate device id \"$id\" in ${file.name}")
            val name = kotlinName(spec, file.name)
            names.put(name, id)?.let { clash ->
                throw GradleException("${file.name}: property name \"$name\" collides with $clash")
            }
            preset(name, spec)
        }

        val source = buildString {
            appendLine("// GENERATED — DO NOT EDIT.")
            appendLine("//")
            appendLine("// Source: cmpdevicepreview/device_specs/*.json")
            appendLine("// Regenerated by the generateDevicePresets Gradle task.")
            appendLine()
            appendLine("package com.apadmi.devicepreview.devices")
            appendLine()
            appendLine("import androidx.compose.ui.geometry.Offset")
            appendLine("import androidx.compose.ui.geometry.Size")
            appendLine("import com.apadmi.devicepreview.core.DeviceFrame")
            appendLine("import com.apadmi.devicepreview.core.DeviceInsets")
            appendLine("import com.apadmi.devicepreview.core.DeviceKind")
            appendLine("import com.apadmi.devicepreview.core.DevicePreset")
            appendLine("import com.apadmi.devicepreview.core.DeviceSystemUi")
            appendLine("import com.apadmi.devicepreview.core.DeviceType")
            appendLine("import com.apadmi.devicepreview.core.SystemUiBar")
            appendLine()
            appendLine("/**")
            appendLine(" * The built-in device catalog: ${presets.size} devices, generated from the device specs")
            appendLine(" * shared with flutter_device_preview — screen size, pixel ratio, safe areas, frame")
            appendLine(" * artwork, status bar artwork and keyboard heights included.")
            appendLine(" */")
            appendLine("public object DevicePresets {")
            for (preset in presets) append(preset.property)
            appendLine("    /** All built-in presets, sorted by id. */")
            appendLine("    public val all: List<DevicePreset> = listOf(")
            for (preset in presets) appendLine("        ${preset.name},")
            appendLine("    )")
            appendLine()
            appendLine("    /** Returns the built-in preset with the given [id], or null. */")
            appendLine("    public fun byId(id: String): DevicePreset? = all.firstOrNull { it.id == id }")
            // One builder function per preset keeps each JVM method, and the object's static
            // initializer, far from the 64 KB method size limit.
            for (preset in presets) {
                appendLine()
                append(preset.builder)
            }
            appendLine("}")
        }

        val output = outputDirectory.get().asFile
        output.deleteRecursively()
        output.resolve("com/apadmi/devicepreview/devices/DevicePresets.kt").apply {
            parentFile.mkdirs()
            writeText(source)
        }
    }

    /** A preset's public property, and the private function that builds it. */
    private class Preset(val name: String, val property: String, val builder: String)

    private fun preset(name: String, spec: Map<String, Any?>): Preset {
        val fileName = "${spec["id"]}.json"
        val displayName = string(spec, "name", fileName)
        val brand = spec["brand"]?.let { string(spec, "brand", fileName) }
        val year = spec["year"]?.let { it as? Int ?: throw GradleException("$fileName: \"year\" must be an integer") }
        val type = when (val platform = string(spec, "platform", fileName)) {
            "android", "fuchsia" -> "ANDROID"
            "iOS" -> "IOS"
            "macOS", "windows", "linux" -> "OTHER"
            else -> throw GradleException("$fileName: unknown platform \"$platform\"")
        }
        val kind = when (val kind = spec["kind"] ?: "phone") {
            "phone", "tablet", "foldable", "desktop" -> (kind as String).uppercase()
            else -> throw GradleException("$fileName: unknown kind \"$kind\"")
        }
        val size = map(spec["portraitSize"], "portraitSize", fileName)
        val width = number(size["width"], "portraitSize.width", fileName)
        val height = number(size["height"], "portraitSize.height", fileName)
        val pixelRatio = number(spec["devicePixelRatio"], "devicePixelRatio", fileName)
        if (width <= 0 || height <= 0 || pixelRatio <= 0) {
            throw GradleException("$fileName: portraitSize and devicePixelRatio must be positive")
        }

        val details = listOfNotNull(brand, year?.toString()).joinToString(", ")
        val summary = "${format(width)} × ${format(height)} at ${format(pixelRatio)}x"
        val property = buildString {
            appendLine("    /** $displayName${if (details.isEmpty()) "" else " ($details)"}: $summary. */")
            appendLine("    public val $name: DevicePreset = ${name}Preset()")
            appendLine()
        }
        val builder = buildString {
            appendLine("    private fun ${name}Preset(): DevicePreset = DevicePreset(")
            appendLine("        id = ${literal(spec["id"] as String)},")
            appendLine("        name = ${literal(displayName)},")
            appendLine("        type = DeviceType.$type,")
            appendLine("        kind = DeviceKind.$kind,")
            if (brand != null) appendLine("        brand = ${literal(brand)},")
            if (year != null) appendLine("        year = $year,")
            appendLine("        portraitSize = Size(${float(width)}, ${float(height)}),")
            appendLine("        devicePixelRatio = ${float(pixelRatio)},")
            spec["portraitPadding"]?.let { appendLine("        portraitSafeArea = ${insets(it, "portraitPadding", fileName)},") }
            spec["landscapePadding"]?.let { appendLine("        landscapeSafeArea = ${insets(it, "landscapePadding", fileName)},") }
            spec["frame"]?.let { append(frame(map(it, "frame", fileName), fileName)) }
            spec["systemUi"]?.let { append(systemUi(map(it, "systemUi", fileName), fileName)) }
            // The keyboard covers part of the screen's height in its orientation: the portrait
            // height in portrait, the portrait width in landscape.
            keyboardHeight(spec, "portraitKeyboardHeight", height, fileName)?.let {
                appendLine("        portraitKeyboardHeight = ${float(it)},")
            }
            keyboardHeight(spec, "landscapeKeyboardHeight", width, fileName)?.let {
                appendLine("        landscapeKeyboardHeight = ${float(it)},")
            }
            appendLine("    )")
        }
        return Preset(name, property, builder)
    }

    private fun frame(frame: Map<String, Any?>, fileName: String): String = buildString {
        val size = map(frame["size"], "frame.size", fileName)
        appendLine("        frame = DeviceFrame(")
        appendLine(
            "            size = Size(${float(number(size["width"], "frame.size.width", fileName))}, " +
                "${float(number(size["height"], "frame.size.height", fileName))}),"
        )
        frame["screenOffset"]?.let {
            val offset = map(it, "frame.screenOffset", fileName)
            appendLine(
                "            screenOffset = Offset(${float(number(offset["x"], "frame.screenOffset.x", fileName))}, " +
                    "${float(number(offset["y"], "frame.screenOffset.y", fileName))}),"
            )
        }
        frame["screenPath"]?.let {
            val path = it as? String ?: throw GradleException("$fileName: frame.screenPath must be a string")
            if (path.isNotEmpty()) appendLine("            screenPath = ${literal(path)},")
        }
        artwork("body", artworkLines(frame["body"], "frame.body", fileName), indent = "            ")?.let(::append)
        appendLine("        ),")
    }

    /** `systemUi`, minus its `platform`; empty bars are left out, and so is an empty `systemUi`. */
    private fun systemUi(systemUi: Map<String, Any?>, fileName: String): String {
        val bars = listOf("statusBar", "navigationBar").mapNotNull { key ->
            systemUi[key]?.let { bar(map(it, "systemUi.$key", fileName), key, fileName) }
        }
        if (bars.isEmpty()) return ""
        return buildString {
            appendLine("        systemUi = DeviceSystemUi(")
            for (bar in bars) append(bar)
            appendLine("        ),")
        }
    }

    private fun bar(bar: Map<String, Any?>, key: String, fileName: String): String? {
        val slots = listOf("leading", "center", "trailing").mapNotNull { slot ->
            artwork(slot, artworkLines(bar[slot], "systemUi.$key.$slot", fileName), indent = "                ")
        }
        if (slots.isEmpty()) return null
        return buildString {
            appendLine("            $key = SystemUiBar(")
            for (slot in slots) append(slot)
            for (inset in listOf("inset", "bottomInset")) {
                val value = bar[inset]?.let { number(it, "systemUi.$key.$inset", fileName) } ?: continue
                if (value < 0) throw GradleException("$fileName: systemUi.$key.$inset must not be negative")
                appendLine("                $inset = ${float(value)},")
            }
            appendLine("            ),")
        }
    }

    private fun keyboardHeight(spec: Map<String, Any?>, key: String, extent: Double, fileName: String): Double? {
        val height = spec[key]?.let { number(it, key, fileName) } ?: return null
        if (height <= 0 || height > extent) {
            throw GradleException("$fileName: \"$key\" must be positive and at most ${format(extent)}")
        }
        return height
    }

    /** SVG artwork: a string, or an array of lines joined with newlines. Null when absent or empty. */
    private fun artworkLines(value: Any?, key: String, fileName: String): List<String>? {
        val lines = when (value) {
            null -> return null
            is String -> listOf(value)
            is List<*> -> value.map { it as? String ?: throw GradleException("$fileName: $key lines must be strings") }
            else -> throw GradleException("$fileName: $key must be a string or an array of strings")
        }
        return lines.takeUnless { it.isEmpty() || it.all(String::isEmpty) }
    }

    /** A `name = listOf(…).joinToString("\n"),` argument, keeping the spec's lines for readability. */
    private fun artwork(name: String, lines: List<String>?, indent: String): String? {
        if (lines == null) return null
        return buildString {
            appendLine("$indent$name = listOf(")
            for (line in lines) appendLine("$indent    ${literal(line)},")
            appendLine("$indent).joinToString(\"\\n\"),")
        }
    }

    private fun insets(value: Any?, key: String, fileName: String): String {
        val insets = map(value, key, fileName)
        val sides = listOf("left", "top", "right", "bottom").map { side ->
            "$side = ${float(insets[side]?.let { number(it, "$key.$side", fileName) } ?: 0.0)}"
        }
        return "DeviceInsets(${sides.joinToString(", ")})"
    }

    /**
     * The Kotlin property name of a spec, derived like the Flutter generator's Dart names: the brand
     * token is dropped and the rest camel-cased (`apple-iphone-16-pro` → `iPhone16Pro`,
     * `samsung-galaxy-z-fold-8` → `galaxyZFold8`).
     */
    private fun kotlinName(spec: Map<String, Any?>, fileName: String): String {
        val id = string(spec, "id", fileName)
        nameOverrides[id]?.let { return it }
        var tokens = id.split('-')
        val brand = (spec["brand"] as? String)?.lowercase()
        if (tokens.size > 1 && tokens.first() == brand) tokens = tokens.drop(1)
        val name = tokens.mapIndexed { index, raw ->
            val token = tokenSpellings[raw] ?: raw
            if (token.isEmpty()) throw GradleException("$fileName: id \"$id\" has an empty token")
            if (index == 0) token else token.replaceFirstChar { it.uppercaseChar() }
        }.joinToString("")
        if (!Regex("^[a-zA-Z_][a-zA-Z0-9_]*$").matches(name)) {
            throw GradleException(
                "$fileName: derived property name \"$name\" is not a valid identifier; " +
                    "add the id to nameOverrides in device-presets.gradle.kts"
            )
        }
        return name
    }

    private fun string(spec: Map<String, Any?>, key: String, fileName: String): String =
        spec[key] as? String ?: throw GradleException("$fileName: \"$key\" must be a string")

    @Suppress("UNCHECKED_CAST")
    private fun map(value: Any?, key: String, fileName: String): Map<String, Any?> =
        value as? Map<String, Any?> ?: throw GradleException("$fileName: \"$key\" must be an object")

    private fun number(value: Any?, key: String, fileName: String): Double =
        (value as? Number)?.toDouble() ?: throw GradleException("$fileName: \"$key\" must be a number")

    private fun format(value: Double): String =
        if (value == Math.floor(value) && Math.abs(value) < 1e9) value.toLong().toString() else value.toString()

    private fun float(value: Double): String = "${format(value)}f"

    private fun literal(value: String): String {
        // A JVM class file caps each string constant at 65535 bytes.
        if (value.toByteArray(Charsets.UTF_8).size > 60_000) {
            throw GradleException("A device spec string is too long to embed (${value.length} chars)")
        }
        val escaped = buildString {
            for (char in value) {
                when (char) {
                    '\\' -> append("\\\\")
                    '"' -> append("\\\"")
                    '$' -> append("\\$")
                    '\n' -> append("\\n")
                    '\r' -> append("\\r")
                    '\t' -> append("\\t")
                    else -> append(char)
                }
            }
        }
        return "\"$escaped\""
    }

    private companion object {
        /** Ids whose property name cannot be derived from the id itself. */
        val nameOverrides = mapOf(
            "desktop-small" to "smallDesktopWindow",
            "desktop-large" to "largeDesktopWindow",
        )

        /** Id tokens with a spelling other than plain capitalization. */
        val tokenSpellings = mapOf(
            "iphone" to "iPhone",
            "ipad" to "iPad",
        )
    }
}

tasks.register<GenerateDevicePresetsTask>("generateDevicePresets") {
    group = "build"
    description = "Generates the DevicePresets catalog from device_specs/*.json."
    specFiles.from(fileTree("device_specs") { include("*.json") })
    outputDirectory.set(layout.buildDirectory.dir("generated/devicePresets/kotlin"))
}
